 const [view,setView]=useState('Overview'); const [menuOpen,setMenuOpen]=useState(false); const [rows,setRows]=useState<Row[]>([]); const [finnSeed,setFinnSeed]=useState(''); const [identityHandoff,setIdentityHandoff]=useState<any>(null); const [finnSession,setFinnSession]=useState<any>(null)
