 useEffect(()=>{const n=localStorage.getItem('flip-lead-buyer-name')||'Buyer';setBuyerName(n);setBuyerNameDraft(n);try{const savedRules=localStorage.getItem('flip-lead-buying-rules');if(savedRules){const parsed=JSON.parse(savedRules);if(Number(parsed.profit)===200)parsed.profit=defaults.profit;setRules({...defaults,...parsed})}const savedBudget=localStorage.getItem('flip-lead-buying-budget');if(savedBudget!==null&&Number.isFinite(Number(savedBudget))&&Number(savedBudget)>0)setBudget(Number(savedBudget))}catch{}setSettingsLoaded(true)},[])
 useEffect(()=>{if(!settingsLoaded)return;localStorage.setItem('flip-lead-buying-rules',JSON.stringify(rules))},[rules,settingsLoaded])
