 const saveFinnOpportunity=(r:any)=>{const b=r.best||{};const buy=Number(r.bestUnitCost||b.effectiveUnitCost||b.unitCost||0);const qty=Math.max(1,Number(b.caseQty||1));const readiness=buyingReadiness({confidence:r.identityConfidence,usablePrice:buy>0,amazonMatched:!!r.amazonMatched,feesKnown:false,demandKnown:false,sameVariant:r.sameVariant!==false,sameSize:r.sameSize!==false});const item:Row={id:'finn-'+Date.now(),product:r.product||b.product||'Supplier product',ean:b.ean||'',asin:b.asin||'',supplier:b.supplier||b.source||'',buy,sell:0,qty,status:'Shortlisted',decision:'CONSIDER',identityStatus:r.identityConfidence||'UNVERIFIED',finnStatus:readiness.ready?'READY':'NOT READY'};setRows(v=>[item,...v.filter(x=>!(item.ean&&x.ean===item.ean&&x.supplier===item.supplier))]);setView('Opportunities')}
 const purchase=(id:string)=>setRows(rows.map(r=>r.id===id?{...r,status:'Purchased'}:r))
