 {view==='Portfolio'&&(()=>{const portfolioRows=rows.filter(r=>['Purchased','Selling','Completed'].includes(r.status));const activeRows=portfolioRows.filter(r=>r.status!=='Completed');const invested=activeRows.reduce((s,r)=>s+r.buy*r.qty,0);const units=activeRows.reduce((s,r)=>s+r.qty,0);const profit=portfolioRows.filter(r=>r.status==='Completed').reduce((s,r)=>s+((r.actualSell??r.sell)-r.buy)*r.qty,0);return <><Title k="HOLDINGS" t="Portfolio" p="Products you have actually bought and the outcomes you record."/><div className="cards"><Metric l="Stock invested" v={gbp(invested)}/><Metric l="Stock on hand" v={String(units)}/><Metric l="Realised profit" v={gbp(profit)}/><Metric l="Completed products" v={String(portfolioRows.filter(r=>r.status==='Completed').length)}/></div>{portfolioRows.length===0?<section className="emptyState"><b>No purchased stock recorded.</b><span>Shortlisted Opportunities do not count as stock or committed capital.</span></section>:<section><div className="sectionHead"><div><small>ACTUAL HOLDINGS</small><h2>Purchased products</h2><p>Only products you have explicitly recorded as purchased belong here.</p></div><button onClick={clearPortfolio}>Clear Portfolio</button></div><div className="table"><table><thead><tr><th>Product</th><th>Supplier</th><th>Qty</th><th>Unit cost</th><th>Purchase cost</th><th>Status</th><th>Action</th></tr></thead><tbody>{portfolioRows.map(r=><tr key={r.id}><td><b>{r.product}</b><small>{r.ean}</small></td><td>{r.supplier||'—'}</td><td>{r.qty}</td><td>{gbp(r.buy)}</td><td><b>{gbp(r.buy*r.qty)}</b></td><td>{r.status}</td><td><button onClick={()=>removePortfolioItem(r.id)}>Remove</button></td></tr>)}</tbody></table></div></section>}</>})()}
 {view==='Profile'&&<><Title k="YOUR ACCOUNT" t="Profile & settings" p="Manage your buyer identity, buying rules and budget."/>
 <div className="profile"><div><small>YOUR BUYING PROFILE</small><h2>Balanced</h2><p>Source Stack prioritises healthy returns while limiting exposure on untested products.</p></div><div className="profileStats"><b>7 rules active</b><span>Monthly budget {gbp(budget)}</span></div></div>
 <div className="settingsAccordion">
  <section className="settingsFold"><button className="settingsFoldHead" onClick={()=>setSettingsOpen(settingsOpen==='buyer'?null:'buyer')}><div><small>VIRTUAL BUYER</small><h2>Buyer identity</h2><span>{buyerName}</span></div><b>{settingsOpen==='buyer'?'−':'+'}</b></button>{settingsOpen==='buyer'&&<div className="settingsFoldBody"><label><small>BUYER NAME</small><input value={buyerNameDraft} maxLength={24} onChange={e=>{setBuyerNameDraft(e.target.value);setBuyerNameSaved(false)}}/></label><div className="quick"><button className="primary" onClick={saveBuyerName}>Save buyer name</button>{buyerNameSaved&&<small>Saved as {buyerName}</small>}</div></div>}</section>
  <section className="settingsFold"><button className="settingsFoldHead" onClick={()=>setSettingsOpen(settingsOpen==='returns'?null:'returns')}><div><small>01 · RETURNS</small><h2>Financial Rules</h2><span>ROI ≥{rules.roi}% · Profit ≥{gbp(rules.profit)} · Margin ≥{rules.margin}% · Total ≥{gbp(rules.totalProfit)}</span></div><b>{settingsOpen==='returns'?'−':'+'}</b></button>{settingsOpen==='returns'&&<div className="settingsFoldBody"><Rule label="Minimum ROI" help="Minimum return required on the cost of the stock." value={rules.roi} unit="%" set={v=>setRules({...rules,roi:v})}/><Rule label="Minimum profit per unit" help="Projected profit after selling and fulfilment costs." value={rules.profit} prefix="£" set={v=>setRules({...rules,profit:v})}/><Rule label="Minimum margin" help="Minimum profit as a percentage of selling price." value={rules.margin} unit="%" set={v=>setRules({...rules,margin:v})}/><Rule label="Minimum total opportunity profit" help="Stops high-ROI but low-value opportunities passing." value={rules.totalProfit} prefix="£" set={v=>setRules({...rules,totalProfit:v})}/></div>}</section>
  <section className="settingsFold"><button className="settingsFoldHead" onClick={()=>setSettingsOpen(settingsOpen==='exposure'?null:'exposure')}><div><small>02 · EXPOSURE</small><h2>Exposure Rules</h2><span>First buy ≤{gbp(rules.firstCapital)} · ≤{rules.firstUnits} units · Product ≤{gbp(rules.maxCapital)}</span></div><b>{settingsOpen==='exposure'?'−':'+'}</b></button>{settingsOpen==='exposure'&&<div className="settingsFoldBody"><Rule label="Maximum first purchase" help="Limits capital exposure when testing a product for the first time." value={rules.firstCapital} prefix="£" set={v=>setRules({...rules,firstCapital:v})}/><Rule label="Maximum initial quantity" help="Preferred ceiling for a first order of an unproven product." value={rules.firstUnits} unit="units" set={v=>setRules({...rules,firstUnits:v})}/><Rule label="Maximum capital per product" help="Maximum total capital Source Stack allows in one opportunity." value={rules.maxCapital} prefix="£" set={v=>setRules({...rules,maxCapital:v})}/></div>}</section>
  <section className="settingsFold"><button className="settingsFoldHead" onClick={()=>setSettingsOpen(settingsOpen==='capital'?null:'capital')}><div><small>03 · CAPITAL MANAGEMENT</small><h2>Monthly Buying Budget</h2><span>{gbp(Math.max(0,budget-active))} available · {gbp(budget)} budget</span></div><b>{settingsOpen==='capital'?'−':'+'}</b></button>{settingsOpen==='capital'&&<div className="settingsFoldBody"><Rule label="Monthly buying budget" help={gbp(active)+' currently committed to active purchases.'} value={budget} prefix="£" set={setBudget}/><div className="budgetBar"><i style={{width:Math.min(100,active/budget*100)+'%'}}/></div><div className="budgetLabels"><span>{gbp(active)} committed</span><span>{Math.round(active/budget*100)}% used</span><span>{gbp(budget)} budget</span></div></div>}</section>
  <section className="settingsFold"><button className="settingsFoldHead" onClick={()=>setSettingsOpen(settingsOpen==='decisions'?null:'decisions')}><div><small>DECISION ENGINE</small><h2>How Source Stack uses your rules</h2><span>BUY · TEST BUY · CONSIDER · WALK AWAY</span></div><b>{settingsOpen==='decisions'?'−':'+'}</b></button>{settingsOpen==='decisions'&&<div className="settingsFoldBody"><div className="decisionCards"><Decision n="BUY" c="buy" text="Meets the financial rules with acceptable exposure and sufficient confidence."/><Decision n="TEST BUY" c="testbuy" text="Economics pass, but price confidence, history or first-buy exposure needs proving."/><Decision n="CONSIDER" c="consider" text="Potential opportunity, but one or more thresholds need investigation."/><Decision n="WALK AWAY" c="walkaway" text="Fails a hard buying rule or does not justify the capital required."/></div><div className="quick"><button className="reset" onClick={()=>{setRules(defaults);setBudget(2000)}}>Reset to Source Stack defaults</button></div></div>}</section>
 </div></>}
